package remframework.geometry.discovery.configuration;

import remframework.geometry.discovery.*;
import remframework.geometry.discovery.experiment.FaceCompositionMode;
import remframework.geometry.discovery.graph.canonical.Canonicalizer;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

/** Exact dual-triangulation state-space generation for cubic uniform spherical surfaces. */
public final class UniformSphericalFaceGenerator {
    public Outcome generate(ConfigurationRequest request,NormalizedGraphRequest normalized){return generate(request,normalized,GenerationExecution.defaults());}
    public Outcome generate(ConfigurationRequest request,NormalizedGraphRequest normalized,GenerationExecution execution){
        long started=System.nanoTime();UniformSphericalSearchLimits limits=normalized.specializedSearchLimits();long deadline=started+limits.timeLimit().toNanos();
        if(normalized.exactDegree()!=3||normalized.faceComposition().mode()!=FaceCompositionMode.UNIFORM_FACE_SIZE||normalized.expectedFaceCount()==null)return failed("Specialized generation currently requires exact primal K=3, F, and uniform m.",limits,started);
        int dualVertices=Math.toIntExact(normalized.expectedFaceCount()),dualDegree=normalized.faceComposition().commonFaceEdgeCount(),workers=execution.workers().resolve();
        if(dualVertices<4)return failed("A closed triangular dual requires at least four vertices.",limits,started);
        ConcurrentMap<String,LongAdder> pruning=new ConcurrentHashMap<>();AtomicLong examined=new AtomicLong(),duplicates=new AtomicLong(),completed=new AtomicLong();AtomicInteger active=new AtomicInteger();AtomicBoolean limited=new AtomicBoolean();
        Set<String> seen=ConcurrentHashMap.newKeySet(),primalCodes=ConcurrentHashMap.newKeySet();Queue<Configuration> retained=new ConcurrentLinkedQueue<>();
        CombinatorialSurfaceCanonicalizer canonicalizer=new CombinatorialSurfaceCanonicalizer();CombinatorialFaceComplex seed=seedTriangulation(dualVertices);seen.add(DevelopmentTimingDiagnostics.measure("stage1.canonicalization",()->canonicalizer.canonicalize(seed)).code());List<CombinatorialFaceComplex> frontier=List.of(seed);
        ExecutorService pool=Executors.newFixedThreadPool(workers,r->{Thread t=new Thread(r,"uniform-spherical-generator");t.setDaemon(true);return t;});
        try{
            while(!frontier.isEmpty()&&!stop(execution,limited,deadline,examined.get(),frontier.size(),limits)){
                ConcurrentLinkedQueue<CombinatorialFaceComplex> nextFrontier=new ConcurrentLinkedQueue<>();List<Callable<Void>> tasks=new ArrayList<>(frontier.size());
                for(CombinatorialFaceComplex dual:frontier)tasks.add(()->{if(stop(execution,limited,deadline,examined.get(),nextFrontier.size(),limits))return null;active.incrementAndGet();try{
                    long state=examined.incrementAndGet();if((state&255)==0)publish(execution.progress(),started,workers,active.get(),state,duplicates.get(),completed.get(),retained.size(),nextFrontier.size(),pruning,limits,true,false);if(state>limits.maximumPartialStates()){limited.set(true);return null;}
                    if(matchesDegree(dual,dualDegree)){completed.incrementAndGet();retain(request,normalized,dual,canonicalizer,primalCodes,retained,duplicates,pruning,limits,limited);}
                    Map<String,Long> localPruning=new HashMap<>();for(CombinatorialFaceComplex candidate:flips(dual,localPruning)){if(stop(execution,limited,deadline,examined.get(),nextFrontier.size(),limits))break;String code=DevelopmentTimingDiagnostics.measure("stage1.canonicalization",()->canonicalizer.canonicalize(candidate)).code();if(seen.add(code))nextFrontier.add(candidate);else{duplicates.incrementAndGet();increment(pruning,"CANONICAL_PARTIAL_DUPLICATE");}}
                    localPruning.forEach((key,value)->increment(pruning,key,value));return null;
                }finally{active.decrementAndGet();}});
                for(Future<Void> future:pool.invokeAll(tasks)){try{future.get();}catch(ExecutionException failure){limited.set(true);increment(pruning,"WORKER_FAILURE");}}
                publish(execution.progress(),started,workers,active.get(),examined.get(),duplicates.get(),completed.get(),retained.size(),nextFrontier.size(),pruning,limits,true,execution.cancelled().getAsBoolean());
                frontier=new ArrayList<>(nextFrontier);
            }
        }catch(InterruptedException interrupted){Thread.currentThread().interrupt();limited.set(true);}finally{pool.shutdownNow();DevelopmentTimingDiagnostics.record("stage1.frontier-operations",System.nanoTime()-started);}
        boolean cancelled=execution.cancelled().getAsBoolean();if(cancelled)limited.set(true);List<Configuration> ordered=retained.stream().sorted(Comparator.comparing(c->c.id().toString())).toList();
        GenerationCompleteness completeness=limited.get()?GenerationCompleteness.INCOMPLETE_SEARCH_LIMIT_REACHED:GenerationCompleteness.COMPLETE_FOR_SELECTED_PARAMETER_CLASS;String explanation=cancelled?"Generation was cancelled; retained results are incomplete.":limited.get()?"The canonical dual-triangulation frontier reached a configured search limit; retained results are incomplete.":"The connected canonical edge-flip state space of dual triangulations was exhausted for the selected parameter class.";
        Map<String,Long> counts=counts(pruning);GenerationDiagnostics diagnostics=new GenerationDiagnostics(GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION,"2",ConstructionMethod.DUAL_TRIANGULATED_SURFACE,completeness,examined.get(),counts.values().stream().mapToLong(Long::longValue).sum(),completed.get(),duplicates.get(),ordered.size(),counts,limits,workers,explanation);publish(execution.progress(),started,workers,0,examined.get(),duplicates.get(),completed.get(),ordered.size(),frontier.size(),pruning,limits,false,cancelled);return new Outcome(ordered,diagnostics,(System.nanoTime()-started)/1_000_000);
    }
    private static boolean stop(GenerationExecution execution,AtomicBoolean limited,long deadline,long examined,int frontier,UniformSphericalSearchLimits limits){boolean stop=execution.cancelled().getAsBoolean()||limited.get()||System.nanoTime()>=deadline||examined>=limits.maximumPartialStates()||frontier>limits.maximumFrontierStates();if(stop)limited.set(true);return stop;}
    private static boolean matchesDegree(CombinatorialFaceComplex dual,int degree){int[] values=new int[dual.vertexCount()];for(DiscoveryConnection edge:dual.edges()){values[edge.firstNodeId()]++;values[edge.secondNodeId()]++;}return java.util.Arrays.stream(values).allMatch(value->value==degree);}
    private static void retain(ConfigurationRequest request,NormalizedGraphRequest normalized,CombinatorialFaceComplex dual,CombinatorialSurfaceCanonicalizer canonicalizer,Set<String> primalCodes,Queue<Configuration> retained,AtomicLong duplicates,ConcurrentMap<String,LongAdder> pruning,UniformSphericalSearchLimits limits,AtomicBoolean limited){CombinatorialFaceComplex primal=dualize(dual);var validation=new CombinatorialSurfaceValidator().validate(primal,Math.toIntExact(normalized.expectedEdgeCount()),Math.toIntExact(normalized.expectedFaceCount()),normalized.exactDegree(),normalized.faceComposition().commonFaceEdgeCount(),normalized.surfaceTopologyAssumption().eulerCharacteristic());if(!validation.valid()){validation.failures().forEach(failure->increment(pruning,failure));return;}var canonical=DevelopmentTimingDiagnostics.measure("stage1.canonicalization",()->canonicalizer.canonicalize(primal));String graphLabel=primal.vertexCount()<=ConfigurationGenerator.MAX_EXHAUSTIVE_N?new Canonicalizer().canonicalLabel(primal.vertexCount(),validation.edges()):canonical.code();if(!primalCodes.add(graphLabel)){duplicates.incrementAndGet();increment(pruning,"DUPLICATE_ISOMORPH");return;}if(retained.size()>=limits.maximumCompletedConfigurations()){limited.set(true);return;}CombinatorialFaceComplex canonicalPrimal=canonicalRelabel(primal,canonical.vertexLabels());retained.add(configuration(request,normalized,canonicalPrimal,canonicalPrimal.edges(),graphLabel,canonical,retained.size()+1,false));}
    private static CombinatorialFaceComplex canonicalRelabel(CombinatorialFaceComplex surface,int[] labels){List<List<Integer>> faces=surface.faces().stream().map(face->canonicalOrientedCycle(face.stream().map(vertex->labels[vertex]).toList())).sorted(UniformSphericalFaceGenerator::compareCycle).toList();return new CombinatorialFaceComplex(surface.vertexCount(),faces);}
    private static List<Integer> canonicalOrientedCycle(List<Integer> cycle){List<Integer> best=null;for(int start=0;start<cycle.size();start++){List<Integer> rotated=new ArrayList<>();for(int i=0;i<cycle.size();i++)rotated.add(cycle.get((start+i)%cycle.size()));if(best==null||compareCycle(rotated,best)<0)best=rotated;}return List.copyOf(best);}
    private static int compareCycle(List<Integer> a,List<Integer> b){for(int i=0;i<Math.min(a.size(),b.size());i++){int compared=Integer.compare(a.get(i),b.get(i));if(compared!=0)return compared;}return Integer.compare(a.size(),b.size());}
    private static void increment(ConcurrentMap<String,LongAdder> counts,String key){increment(counts,key,1);}
    private static void increment(ConcurrentMap<String,LongAdder> counts,String key,long value){counts.computeIfAbsent(key,ignored->new LongAdder()).add(value);}
    private static Map<String,Long> counts(ConcurrentMap<String,LongAdder> values){Map<String,Long> result=new TreeMap<>();values.forEach((key,value)->result.put(key,value.sum()));return result;}
    private static void publish(Consumer<GenerationProgress> listener,long started,int workers,int active,long examined,long duplicates,long completed,int retained,int frontier,ConcurrentMap<String,LongAdder> pruning,UniformSphericalSearchLimits limits,boolean running,boolean cancelled){long elapsed=Math.max(1,System.nanoTime()-started);Map<String,Long> counts=counts(pruning);listener.accept(new GenerationProgress(GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION,workers,active,java.time.Duration.ofNanos(elapsed),examined,examined*1_000_000_000d/elapsed,counts.values().stream().mapToLong(Long::longValue).sum(),frontier,completed,duplicates,retained,counts,limits,running,cancelled));}
    private static Configuration configuration(ConfigurationRequest request,NormalizedGraphRequest normalized,CombinatorialFaceComplex primal,List<DiscoveryConnection> edges,String label,CombinatorialSurfaceCanonicalizer.Result canonical,int index,boolean complete){String hash=shortHash(label);var diagnostic=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.COMPLETE,GeometryConfigurationStatusCode.ELIGIBLE_FOR_GEOMETRY_TEST,"Uniform spherical topology generated","A coordinate-free primal face complex passed independent closed-manifold validation after dual construction.");return new Configuration(new ConfigurationId("cfg-"+hash),primal.vertexCount(),normalized.exactDegree(),edges,null,label,hash,canonical.automorphismCount(),canonical.vertexTransitive()?GraphSymmetryClassification.HIGHLY_SYMMETRIC:canonical.automorphismCount()>1?GraphSymmetryClassification.SYMMETRIC:GraphSymmetryClassification.ASYMMETRIC,true,index,GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION.name(),complete,GeometryConfigurationStatus.of(diagnostic),List.of(diagnostic),Instant.now(),Map.of("constructionMethod",ConstructionMethod.DUAL_TRIANGULATED_SURFACE.name(),"combinatorialFaces",primal.encode(),"strategyVersion","1"));}
    private static CombinatorialFaceComplex seedTriangulation(int vertices){List<List<Integer>> faces=new ArrayList<>(List.of(List.of(0,2,1),List.of(0,1,3),List.of(1,2,3),List.of(2,0,3)));for(int vertex=4;vertex<vertices;vertex++){List<Integer> face=faces.removeFirst();int a=face.get(0),b=face.get(1),c=face.get(2);faces.add(List.of(a,b,vertex));faces.add(List.of(b,c,vertex));faces.add(List.of(c,a,vertex));}return new CombinatorialFaceComplex(vertices,faces);}
    private static List<CombinatorialFaceComplex> flips(CombinatorialFaceComplex surface,Map<String,Long> pruning){Map<Long,List<Integer>> incident=new TreeMap<>();for(int fi=0;fi<surface.faces().size();fi++){List<Integer> face=surface.faces().get(fi);for(int i=0;i<3;i++){DiscoveryConnection edge=new DiscoveryConnection(face.get(i),face.get((i+1)%3));incident.computeIfAbsent(edge.undirectedKey(),ignored->new ArrayList<>()).add(fi);}}Set<Long> existing=incident.keySet();List<CombinatorialFaceComplex> result=new ArrayList<>();for(var entry:incident.entrySet()){if(entry.getValue().size()!=2){pruning.merge("EDGE_FACE_INCIDENCE_FAILED",1L,Long::sum);continue;}int first=entry.getValue().get(0),second=entry.getValue().get(1);List<Integer>a=surface.faces().get(first),b=surface.faces().get(second);int u=(int)(entry.getKey()>>32),v=(int)(long)entry.getKey();int c=opposite(a,u,v),d=opposite(b,u,v);if(c==d||existing.contains(new DiscoveryConnection(c,d).undirectedKey())){pruning.merge("NON_FLIPPABLE_EDGE",1L,Long::sum);continue;}List<Integer> orientedA=orientEdge(a,u,v),orientedB=orientEdge(b,v,u);if(orientedA==null||orientedB==null){orientedA=orientEdge(a,v,u);orientedB=orientEdge(b,u,v);if(orientedA==null||orientedB==null){pruning.merge("INVALID_LOCAL_MANIFOLD",1L,Long::sum);continue;}int swap=u;u=v;v=swap;c=orientedA.get(2);d=orientedB.get(2);}else{c=orientedA.get(2);d=orientedB.get(2);}List<List<Integer>> faces=new ArrayList<>(surface.faces());faces.set(first,List.of(c,d,v));faces.set(second,List.of(d,c,u));result.add(new CombinatorialFaceComplex(surface.vertexCount(),faces));}return result;}
    private static int opposite(List<Integer> face,int a,int b){return face.stream().filter(v->v!=a&&v!=b).findFirst().orElseThrow();}
    private static List<Integer> orientEdge(List<Integer> face,int a,int b){for(int i=0;i<3;i++)if(face.get(i)==a&&face.get((i+1)%3)==b)return List.of(a,b,face.get((i+2)%3));return null;}
    private static int degree(CombinatorialFaceComplex surface,int vertex){Set<Integer> neighbors=new HashSet<>();for(DiscoveryConnection edge:surface.edges())if(edge.firstNodeId()==vertex)neighbors.add(edge.secondNodeId());else if(edge.secondNodeId()==vertex)neighbors.add(edge.firstNodeId());return neighbors.size();}
    private static CombinatorialFaceComplex dualize(CombinatorialFaceComplex dual){List<List<Integer>> primalFaces=new ArrayList<>();for(int vertex=0;vertex<dual.vertexCount();vertex++){List<Integer> incident=new ArrayList<>();for(int fi=0;fi<dual.faces().size();fi++)if(dual.faces().get(fi).contains(vertex))incident.add(fi);Map<Integer,Set<Integer>> adjacency=new HashMap<>();incident.forEach(face->adjacency.put(face,new TreeSet<>()));for(int i:incident)for(int j:incident)if(i<j&&sharedEdgeAtVertex(dual.faces().get(i),dual.faces().get(j),vertex)) {adjacency.get(i).add(j);adjacency.get(j).add(i);}List<Integer> cycle=new ArrayList<>();int start=incident.stream().min(Integer::compare).orElseThrow(),previous=-1,current=start;do{cycle.add(current);List<Integer> next=adjacency.get(current).stream().toList();int selected=next.get(0)==previous?next.get(1):next.get(0);previous=current;current=selected;}while(current!=start&&cycle.size()<=incident.size());primalFaces.add(cycle);}return new CombinatorialFaceComplex(dual.faces().size(),orientConsistently(primalFaces));}
    private static boolean sharedEdgeAtVertex(List<Integer>a,List<Integer>b,int vertex){Set<Integer> shared=new HashSet<>(a);shared.retainAll(b);return shared.size()==2&&shared.contains(vertex);}
    private static List<List<Integer>> orientConsistently(List<List<Integer>> faces){List<List<Integer>> result=new ArrayList<>();for(List<Integer> face:faces)result.add(new ArrayList<>(face));Map<Long,List<Integer>> incident=new HashMap<>();for(int fi=0;fi<result.size();fi++)for(int i=0;i<result.get(fi).size();i++)incident.computeIfAbsent(new DiscoveryConnection(result.get(fi).get(i),result.get(fi).get((i+1)%result.get(fi).size())).undirectedKey(),ignored->new ArrayList<>()).add(fi);boolean[] done=new boolean[result.size()];ArrayDeque<Integer> q=new ArrayDeque<>();done[0]=true;q.add(0);while(!q.isEmpty()){int current=q.remove();List<Integer> face=result.get(current);for(int i=0;i<face.size();i++){int a=face.get(i),b=face.get((i+1)%face.size());for(int other:incident.get(new DiscoveryConnection(a,b).undirectedKey()))if(!done[other]){if(hasDirectedEdge(result.get(other),a,b))Collections.reverse(result.get(other));done[other]=true;q.add(other);}}}return result.stream().map(List::copyOf).toList();}
    private static boolean hasDirectedEdge(List<Integer>face,int a,int b){for(int i=0;i<face.size();i++)if(face.get(i)==a&&face.get((i+1)%face.size())==b)return true;return false;}
    private static Outcome failed(String explanation,UniformSphericalSearchLimits limits,long started){return new Outcome(List.of(),new GenerationDiagnostics(GenerationStrategy.UNIFORM_SPHERICAL_FACE_GENERATION,"2",ConstructionMethod.DUAL_TRIANGULATED_SURFACE,GenerationCompleteness.FAILED_GENERATION,0,0,0,0,0,Map.of(),limits,1,explanation),(System.nanoTime()-started)/1_000_000);}
    private static String shortHash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8))).substring(0,12);}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    public record Outcome(List<Configuration> configurations,GenerationDiagnostics diagnostics,long elapsedMilliseconds){public Outcome{configurations=List.copyOf(configurations);}}
}
